1	import { useEffect, useMemo, useState } from "react";
2	import { Link, useLocation, useParams, Redirect } from "wouter";
3	import { useUser, useClerk } from "@clerk/react";
4	import {
5	  Gamepad2, Plus, Sparkles, ArrowRight, Users, ChevronDown,
6	  LogOut, Shield, User as UserIcon, Folder, Crown, Trash2,
7	  Loader2, Wand2, GraduationCap, BookOpen, MessageSquare, Trophy,
8	} from "lucide-react";
9	import { Button } from "@/components/ui/button";
10	import { Card, CardContent } from "@/components/ui/card";
11	import { Skeleton } from "@/components/ui/skeleton";
12	import { Textarea } from "@/components/ui/textarea";
13	import { Badge } from "@/components/ui/badge";
14	import { useToast } from "@/hooks/use-toast";
15	import {
16	  Dialog, DialogContent, DialogHeader, DialogTitle, DialogFooter, DialogTrigger,
17	} from "@/components/ui/dialog";
18	import { Input } from "@/components/ui/input";
19	import { Label } from "@/components/ui/label";
20	import {
21	  DropdownMenu, DropdownMenuContent, DropdownMenuItem, DropdownMenuSeparator, DropdownMenuTrigger,
22	} from "@/components/ui/dropdown-menu";
23	import {
24	  AlertDialog, AlertDialogAction, AlertDialogCancel, AlertDialogContent,
25	  AlertDialogDescription, AlertDialogFooter, AlertDialogHeader, AlertDialogTitle,
26	} from "@/components/ui/alert-dialog";
27	import { Avatar, AvatarFallback, AvatarImage } from "@/components/ui/avatar";
28	import {
29	  workspacesApi,
30	  type Workspace, type WorkspaceDetail,
31	} from "@/lib/workspaces-api";
32	import { MembersDialog } from "@/components/workspace/members-dialog";
33	import { AiProvidersDialog } from "@/components/workspace/ai-providers-dialog";
34	import { format } from "date-fns";
35	
36	interface Template {
37	  key: string;
38	  title: string;
39	  desc: string;
40	  emoji: string;
41	}
42	
