1	import { useEffect, useRef, useState } from "react";
2	import { useGetProject, useUpdateProject, useGetProjectStats, getGetProjectStatsQueryKey, useCreateEntity, getListEntitiesQueryKey } from "@workspace/api-client-react";
3	import { Card, CardContent, CardHeader, CardTitle, CardDescription } from "@/components/ui/card";
4	import { Input } from "@/components/ui/input";
5	import { Textarea } from "@/components/ui/textarea";
6	import { Label } from "@/components/ui/label";
7	import { Button } from "@/components/ui/button";
8	import { Skeleton } from "@/components/ui/skeleton";
9	import { Badge } from "@/components/ui/badge";
10	import { useDebounce } from "@/hooks/use-debounce";
11	import { AiEditTextarea } from "@/components/workspace/ai-edit-textarea";
12	import { ProjectVersions } from "@/components/workspace/project-versions";
13	import { ComplexityScore } from "@/components/workspace/complexity-score";
14	import {
15	  LayoutDashboard, Activity, Users, FileText, CheckSquare, MessageSquare,
16	  Zap, Sparkles, Settings, MessageCircle, ChevronRight, Flag, BookOpen,
17	  Trophy, Swords, Plus, X, Target, Layers, Loader2,
18	} from "lucide-react";
19	import { useQueryClient } from "@tanstack/react-query";
20	import { GAME_TEMPLATES, type GameTemplate } from "@/lib/game-templates";
21	import { Select, SelectContent, SelectItem, SelectTrigger, SelectValue } from "@/components/ui/select";
22	import { MONOPOLY_ENTITIES } from "@/lib/game-component-types";
23	
24	interface OverviewProps {
25	  projectId: number;
26	  onPromptSend: (prompt: string) => void;
27	}
28	
29	const QUICK_QUESTIONS = [
30	  "What are the biggest design risks in this game?",
31	  "How can I improve player interaction?",
32	  "What rules might conflict with each other?",
33	  "Suggest a unique mechanic based on my entities",
34	  "How does the complexity compare to similar games?",
35	];
36	
37	const QUICK_PROMPTS = [
38	  "Brainstorm core mechanics for this genre.",
39	  "Suggest 5 unique player roles.",
40	  "Draft a quick summary of the rulebook.",
41	  "What are some interesting twists for the endgame?",
42	];
43	
44	const DESIGN_PHASES = [
45	  { value: "concept",   label: "Concept",   desc: "Idea stage — exploring what the game could be",        color: "bg-slate-500/20 text-slate-300 border-slate-500/40" },
46	  { value: "prototype", label: "Prototype", desc: "First playable — rough rules and components",           color: "bg-blue-500/20 text-blue-300 border-blue-500/40" },
47	  { value: "alpha",     label: "Alpha",     desc: "Core loop works — iterating on rules and balance",      color: "bg-violet-500/20 text-violet-300 border-violet-500/40" },
48	  { value: "beta",      label: "Beta",      desc: "Feature complete — polishing and blind playtesting",    color: "bg-amber-500/20 text-amber-300 border-amber-500/40" },
49	  { value: "rc",        label: "Release Candidate", desc: "Print-ready — final checks before manufacturing", color: "bg-emerald-500/20 text-emerald-300 border-emerald-500/40" },
50	] as const;
51	
52	const PHASE_INDEX: Record<string, number> = { concept: 0, prototype: 1, alpha: 2, beta: 3, rc: 4 };
53	
54	type RefGame = { name: string; borrowing: string; avoiding: string };
55	
56	function parseRefGames(raw: string | null | undefined): RefGame[] {
57	  if (!raw) return [];
58	  try { return JSON.parse(raw); } catch { return []; }
59	}
60	
61	function parseTurnPhases(raw: string | null | undefined): string[] {
62	  if (!raw) return [];
63	  try { return JSON.parse(raw); } catch { return raw.split(",").map((s) => s.trim()).filter(Boolean); }
64	}
65	
66	export function Overview({ projectId, onPromptSend }: OverviewProps) {
67	  const queryClient = useQueryClient();
68	  const { data: project, isLoading: projectLoading } = useGetProject(projectId);
69	  const { data: stats, isLoading: statsLoading } = useGetProjectStats(projectId);
70	  const updateProject = useUpdateProject();
71	
72	  const [formData, setFormData] = useState({
73	    name: "", description: "", gameType: "", genre: "", playerCount: "", targetDuration: "",
74	    winCondition: "", eliminationRule: "", designPhase: "concept",
75	  });
76	  const [turnPhaseInput, setTurnPhaseInput] = useState("");
77	  const [turnPhases, setTurnPhases] = useState<string[]>([]);
78	  const [refGames, setRefGames] = useState<RefGame[]>([]);
79	  const [refGameDraft, setRefGameDraft] = useState<RefGame>({ name: "", borrowing: "", avoiding: "" });
80	  const [showRefForm, setShowRefForm] = useState(false);
81	  const [selectedTemplate, setSelectedTemplate] = useState<GameTemplate | null>(null);
82	  const [loadingMonopoly, setLoadingMonopoly] = useState(false);
83	  const createEntity = useCreateEntity();
84	
85	  const debouncedName = useDebounce(formData.name, 1000);
86	  const debouncedDesc = useDebounce(formData.description, 1000);
87	  const debouncedType = useDebounce(formData.gameType, 1000);
88	  const debouncedGenre = useDebounce(formData.genre, 1000);
89	  const debouncedPlayers = useDebounce(formData.playerCount, 1000);
90	  const debouncedDuration = useDebounce(formData.targetDuration, 1000);
91	  const debouncedWin = useDebounce(formData.winCondition, 1200);
92	  const debouncedElim = useDebounce(formData.eliminationRule, 1200);
93	
94	  const initRef = useRef(false);
95	  const lastSavedRef = useRef({ ...formData, turnPhases: "[]", refGames: "[]" });
96	
97	  useEffect(() => {
98	    if (project && !initRef.current) {
99	      const phases = parseTurnPhases(project.turnPhases);
100	      const refs = parseRefGames(project.referenceGames);
101	      const d = {
102	        name: project.name || "",
103	        description: project.description || "",
104	        gameType: project.gameType || "",
105	        genre: project.genre || "",
106	        playerCount: project.playerCount || "",
107	        targetDuration: project.targetDuration || "",
108	        winCondition: project.winCondition || "",
109	        eliminationRule: project.eliminationRule || "",
110	        designPhase: project.designPhase || "concept",
111	      };
112	      setFormData(d);
113	      setTurnPhases(phases);
114	      setRefGames(refs);
115	      lastSavedRef.current = { ...d, turnPhases: JSON.stringify(phases), refGames: JSON.stringify(refs) };
116	      initRef.current = true;
117	    }
118	  }, [project]);
119	
120	  const save = (patch: Parameters<typeof updateProject.mutate>[0]["data"]) => {
121	    updateProject.mutate({ projectId, data: patch });
122	  };
123	
124	  const handleLoadMonopoly = async () => {
125	    if (!confirm("This will add 27 Monopoly component entities to this project as a worked example. Continue?")) return;
126	    setLoadingMonopoly(true);
127	    try {
128	      for (const e of MONOPOLY_ENTITIES) {
129	        await createEntity.mutateAsync({ projectId, data: { name: e.name, type: e.type, subtype: e.subtype, description: e.description } });
130	      }
131	      queryClient.invalidateQueries({ queryKey: getListEntitiesQueryKey(projectId) });
132	    } catch {/* continue on partial failure */}
133	    finally { setLoadingMonopoly(false); }
134	  };
135	
136	  useEffect(() => {
137	    if (!initRef.current) return;
138	    const data = {
139	      name: debouncedName, description: debouncedDesc, gameType: debouncedType,
140	      genre: debouncedGenre, playerCount: debouncedPlayers, targetDuration: debouncedDuration,
141	      winCondition: debouncedWin, eliminationRule: debouncedElim,
142	    };
143	    const changed = Object.keys(data).some((k) => data[k as keyof typeof data] !== (lastSavedRef.current as Record<string, string>)[k]);
144	    if (changed && data.name) {
145	      save(data);
146	      Object.assign(lastSavedRef.current, data);
147	    }
148	    // eslint-disable-next-line react-hooks/exhaustive-deps
149	  }, [debouncedName, debouncedDesc, debouncedType, debouncedGenre, debouncedPlayers, debouncedDuration, debouncedWin, debouncedElim]);
150	
151	  const saveTurnPhases = (phases: string[]) => {
152	    setTurnPhases(phases);
153	    save({ turnPhases: JSON.stringify(phases) });
154	  };
155	
156	  const saveRefGames = (refs: RefGame[]) => {
157	    setRefGames(refs);
158	    save({ referenceGames: JSON.stringify(refs) });
159	  };
160	
161	  const saveDesignPhase = (phase: string) => {
162	    setFormData((f) => ({ ...f, designPhase: phase }));
163	    save({ designPhase: phase });
164	  };
165	
166	  const handleApplyTemplate = (template: GameTemplate) => {
167	    setFormData((f) => ({ ...f, gameType: template.gameType, genre: template.genre, playerCount: template.playerCount, targetDuration: template.targetDuration, description: f.description || template.description }));
168	    setSelectedTemplate(template);
169	  };
170	
171	  if (projectLoading) {
172	    return <div className="space-y-4"><Skeleton className="h-32 w-full" /><Skeleton className="h-64 w-full" /></div>;
173	  }
174	
175	  const currentPhaseIdx = PHASE_INDEX[formData.designPhase] ?? 0;
176	  const currentPhase = DESIGN_PHASES[currentPhaseIdx];
177	
178	  const STATS = [
179	    { label: "Entities", count: stats?.entityCount, icon: LayoutDashboard, color: "text-blue-400", bg: "bg-blue-500/10" },
180	    { label: "Rules", count: stats?.ruleCount, icon: Activity, color: "text-violet-400", bg: "bg-violet-500/10" },
181	    { label: "Players", count: stats?.playerCount, icon: Users, color: "text-emerald-400", bg: "bg-emerald-500/10" },
182	    { label: "Notes", count: stats?.noteCount, icon: FileText, color: "text-amber-400", bg: "bg-amber-500/10" },
183	    { label: "Tasks", count: stats?.taskCount, icon: CheckSquare, color: "text-rose-400", bg: "bg-rose-500/10" },
184	    { label: "Messages", count: stats?.chatMessageCount, icon: MessageSquare, color: "text-sky-400", bg: "bg-sky-500/10" },
185	  ];
186	
187	  return (
188	    <div className="space-y-8 pb-8">
189	
190	      {/* ── Design Phase tracker ─────────────────────────────────────── */}
191	      <Card className="border-border">
192	        <CardHeader className="border-b border-border py-4 px-5 flex-row items-center gap-2">
193	          <Flag className="w-4 h-4 text-primary" />
194	          <div className="flex-1">
195	            <CardTitle className="text-base font-semibold">Design Phase</CardTitle>
196	            <p className="text-xs text-muted-foreground mt-0.5">Track where you are in the design process — the AI adapts its suggestions to your phase.</p>
197	          </div>
198	          <span className={`text-xs font-semibold px-2.5 py-1 rounded-full border ${currentPhase?.color}`}>
199	            {currentPhase?.label}
200	          </span>
201	        </CardHeader>
202	        <CardContent className="px-5 py-4 space-y-3">
203	          <div className="flex gap-1.5 flex-wrap">
204	            {DESIGN_PHASES.map((p, i) => (
205	              <button
206	                key={p.value}
207	                onClick={() => saveDesignPhase(p.value)}
208	                className={`flex-1 min-w-[80px] text-center px-3 py-2 rounded-lg border text-xs font-medium transition-all ${
209	                  formData.designPhase === p.value
210	                    ? `${p.color} ring-1 ring-current`
211	                    : "border-border text-muted-foreground hover:border-primary/40 hover:text-foreground"
212	                }`}
213	              >
214	                <span className="block font-semibold">{p.label}</span>
215	              </button>
216	            ))}
217	          </div>
218	          {/* Phase progress bar */}
219	          <div className="flex items-center gap-2">
220	            <div className="flex-1 h-1.5 bg-muted rounded-full overflow-hidden">
221	              <div
222	                className="h-full bg-primary rounded-full transition-all duration-500"
223	                style={{ width: `${((currentPhaseIdx + 1) / DESIGN_PHASES.length) * 100}%` }}
224	              />
225	            </div>
226	            <span className="text-[10px] text-muted-foreground">{currentPhase?.desc}</span>
227	          </div>
228	        </CardContent>
229	      </Card>
230	
231	      {/* ── Game Templates ───────────────────────────────────────────── */}
232	      <Card className="bg-card border-border border-purple-500/20">
233	        <CardHeader className="border-b border-border py-4 px-5 flex-row items-center gap-2">
234	          <Sparkles className="w-4 h-4 text-purple-400" />
235	          <div className="flex-1">
236	            <CardTitle className="text-base font-semibold flex items-center gap-2">
237	              Game Design Templates
238	              <span className="text-[10px] font-medium bg-purple-500/15 text-purple-300 border border-purple-500/30 px-1.5 py-0.5 rounded">AI-POWERED</span>
239	            </CardTitle>
240	            <p className="text-xs text-muted-foreground mt-0.5">Start with a proven game framework and customize it for your vision.</p>
241	          </div>
242	        </CardHeader>
243	        <CardContent className="px-5 py-4">
244	          <div className="space-y-3">
245	            <Select onValueChange={(value) => { const t = GAME_TEMPLATES.find((t) => t.id === value); if (t) handleApplyTemplate(t); }}>
246	              <SelectTrigger className="flex-1"><SelectValue placeholder="Select a template to apply..." /></SelectTrigger>
247	              <SelectContent>
248	                {GAME_TEMPLATES.map((t) => (
249	                  <SelectItem key={t.id} value={t.id}>
250	                    <div className="flex items-center gap-2"><span className="font-medium">{t.name}</span><span className="text-xs text-muted-foreground">({t.playerCount})</span></div>
251	                  </SelectItem>
252	                ))}
253	              </SelectContent>
254	            </Select>
255	            {selectedTemplate && (
256	              <div className="bg-purple-500/5 border border-purple-500/20 rounded-lg p-3 space-y-2">
257	                <div className="flex items-center justify-between">
258	                  <div><h4 className="text-sm font-medium text-purple-300">{selectedTemplate.name}</h4><p className="text-xs text-muted-foreground">{selectedTemplate.description}</p></div>
259	                  <Button size="sm" variant="outline" className="h-7 text-xs border-purple-500/30 hover:bg-purple-500/10" onClick={() => onPromptSend(`Based on the ${selectedTemplate.name} template, suggest entities, rules, and players for my game "${formData.name}".`)}>
260	                    <Zap className="h-3 w-3 mr-1" /> AI Generate
261	                  </Button>
262	                </div>
263	              </div>
264	            )}
265	          </div>
266	        </CardContent>
267	      </Card>
268	
269	      {/* ── AI Design Advisor ────────────────────────────────────────── */}
270	      <Card className="bg-card border-border border-blue-500/20">
271	        <CardHeader className="border-b border-border py-4 px-5 flex-row items-center gap-2">
272	          <MessageCircle className="w-4 h-4 text-blue-400" />
273	          <div className="flex-1">
274	            <CardTitle className="text-base font-semibold flex items-center gap-2">
275	              AI Design Advisor
276	              <span className="text-[10px] font-medium bg-blue-500/15 text-blue-300 border border-blue-500/30 px-1.5 py-0.5 rounded">QUICK START</span>
277	            </CardTitle>
278	            <p className="text-xs text-muted-foreground mt-0.5">Tap a question to send it to the chat panel.</p>
279	          </div>
280	        </CardHeader>
281	        <CardContent className="px-5 py-4">
282	          <div className="flex flex-wrap gap-1.5">
283	            {QUICK_QUESTIONS.map((q, i) => (
284	              <button key={i} onClick={() => onPromptSend(q)} className="text-xs bg-blue-500/10 border border-blue-500/20 text-blue-300 hover:text-white hover:bg-blue-500/20 rounded-lg px-2.5 py-1.5 transition-colors text-left">{q}</button>
285	            ))}
286	          </div>
287	        </CardContent>
288	      </Card>
289	
290	      {/* ── Stats grid ───────────────────────────────────────────────── */}
291	      <section>
292	        <h3 className="text-sm font-bold uppercase tracking-wider text-muted-foreground mb-3 flex items-center gap-1.5"><Activity className="h-3.5 w-3.5" /> Project at a glance</h3>
293	        <div className="grid grid-cols-2 md:grid-cols-3 lg:grid-cols-6 gap-3">
294	          {STATS.map((stat, i) => (
295	            <Card key={i} className="bg-card border-border">
296	              <CardContent className="p-4">
297	                <div className={`h-8 w-8 rounded-md ${stat.bg} flex items-center justify-center mb-2`}>
298	                  <stat.icon className={`h-4 w-4 ${stat.color}`} />
299	                </div>
300	                {statsLoading ? <Skeleton className="h-7 w-12" /> : <div className="text-2xl font-bold leading-none">{stat.count || 0}</div>}
301	                <div className="text-xs text-muted-foreground mt-1">{stat.label}</div>
302	              </CardContent>
303	            </Card>
304	          ))}
305	        </div>
306	      </section>
307	
308	      <div className="grid grid-cols-1 lg:grid-cols-3 gap-6">
309	        <div className="lg:col-span-2 space-y-6">
310	
311	          {/* ── Project metadata ───────────────────────────────────── */}
312	          <Card>
313	            <CardHeader>
314	              <CardTitle className="flex items-center gap-2 text-lg"><Settings className="h-4 w-4 text-primary" /> Project metadata</CardTitle>
315	              <CardDescription>Changes save automatically — these fields seed every AI prompt.</CardDescription>
316	            </CardHeader>
317	            <CardContent className="space-y-4">
318	              <div className="space-y-2">
319	                <Label htmlFor="name">Project name</Label>
320	                <Input id="name" value={formData.name} onChange={(e) => setFormData((p) => ({ ...p, name: e.target.value }))} />
321	              </div>
322	              <div className="space-y-2">
323	                <Label htmlFor="description">Description</Label>
324	                <AiEditTextarea projectId={projectId} value={formData.description} onChange={(next) => setFormData((p) => ({ ...p, description: next }))} placeholder="A one-paragraph elevator pitch for your game…" rows={4} className="min-h-[100px]" contextLabel="project description" />
325	              </div>
326	              <div className="grid grid-cols-1 sm:grid-cols-2 gap-4">
327	                <div className="space-y-2">
328	                  <Label htmlFor="gameType">Game type</Label>
329	                  <Input id="gameType" placeholder="e.g. Strategy, Party, Worker placement" value={formData.gameType} onChange={(e) => setFormData((p) => ({ ...p, gameType: e.target.value }))} />
330	                </div>
331	                <div className="space-y-2">
332	                  <Label htmlFor="genre">Genre</Label>
333	                  <Input id="genre" placeholder="e.g. Fantasy, Sci-fi, Historical" value={formData.genre} onChange={(e) => setFormData((p) => ({ ...p, genre: e.target.value }))} />
334	                </div>
335	                <div className="space-y-2">
336	                  <Label htmlFor="playerCount">Player count</Label>
337	                  <Input id="playerCount" placeholder="e.g. 2-5" value={formData.playerCount} onChange={(e) => setFormData((p) => ({ ...p, playerCount: e.target.value }))} />
338	                </div>
339	                <div className="space-y-2">
340	                  <Label htmlFor="targetDuration">Target duration</Label>
341	                  <Input id="targetDuration" placeholder="e.g. 45–90 min" value={formData.targetDuration} onChange={(e) => setFormData((p) => ({ ...p, targetDuration: e.target.value }))} />
342	                </div>
343	              </div>
344	            </CardContent>
345	          </Card>
346	
347	          {/* ── Core game loop ──────────────────────────────────────── */}
348	          <Card>
349	            <CardHeader>
350	              <CardTitle className="flex items-center gap-2 text-lg"><Target className="h-4 w-4 text-primary" /> Core game loop</CardTitle>
351	              <CardDescription>The AI uses these to anchor rule suggestions, conflict checks, and balance analysis.</CardDescription>
352	            </CardHeader>
353	            <CardContent className="space-y-4">
354	              {/* Win condition */}
355	              <div className="space-y-2">
356	                <Label className="flex items-center gap-1.5"><Trophy className="w-3.5 h-3.5 text-amber-400" /> Win condition</Label>
357	                <Textarea
358	                  placeholder="e.g. First player to collect 10 Victory Points wins. On a tie, the player with the most Gold wins."
359	                  rows={2}
360	                  value={formData.winCondition}
361	                  onChange={(e) => setFormData((p) => ({ ...p, winCondition: e.target.value }))}
362	                  className="resize-none"
363	                />
364	              </div>
365	
366	              {/* Elimination rule */}
367	              <div className="space-y-2">
368	                <Label className="flex items-center gap-1.5"><Swords className="w-3.5 h-3.5 text-red-400" /> Elimination / losing condition</Label>
369	                <Input
370	                  placeholder="e.g. Players eliminated when Health reaches 0. Last player standing wins."
371	                  value={formData.eliminationRule}
372	                  onChange={(e) => setFormData((p) => ({ ...p, eliminationRule: e.target.value }))}
373	                />
374	              </div>
375	
376	              {/* Turn phases */}
377	              <div className="space-y-2">
378	                <Label className="flex items-center gap-1.5"><Layers className="w-3.5 h-3.5 text-blue-400" /> Turn phases</Label>
379	                {turnPhases.length > 0 && (
380	                  <div className="flex flex-wrap gap-1.5 mb-2">
381	                    {turnPhases.map((phase, i) => (
382	                      <span key={i} className="inline-flex items-center gap-1 text-xs bg-primary/10 border border-primary/25 text-primary rounded px-2 py-0.5">
383	                        <span className="text-[10px] text-muted-foreground font-mono mr-0.5">{i + 1}.</span>
384	                        {phase}
385	                        <button onClick={() => saveTurnPhases(turnPhases.filter((_, j) => j !== i))} className="text-muted-foreground hover:text-destructive ml-0.5">
386	                          <X className="w-2.5 h-2.5" />
387	                        </button>
388	                      </span>
389	                    ))}
390	                  </div>
391	                )}
392	                <div className="flex gap-2">
393	                  <Input
394	                    placeholder="e.g. Draw Phase, Action Phase, Cleanup…"
395	                    value={turnPhaseInput}
396	                    onChange={(e) => setTurnPhaseInput(e.target.value)}
397	                    onKeyDown={(e) => {
398	                      if (e.key === "Enter" && turnPhaseInput.trim()) {
399	                        saveTurnPhases([...turnPhases, turnPhaseInput.trim()]);
400	                        setTurnPhaseInput("");
401	                      }
402	                    }}
403	                  />
404	                  <Button
405	                    type="button" size="sm" variant="outline"
406	                    onClick={() => { if (turnPhaseInput.trim()) { saveTurnPhases([...turnPhases, turnPhaseInput.trim()]); setTurnPhaseInput(""); } }}
407	                    disabled={!turnPhaseInput.trim()}
408	                  >
409	                    <Plus className="w-3.5 h-3.5 mr-1" /> Add
410	                  </Button>
411	                </div>
412	                <p className="text-[10px] text-muted-foreground">Press Enter or click Add. Drag to reorder coming soon.</p>
413	              </div>
414	            </CardContent>
415	          </Card>
416	
417	          {/* ── Reference game shelf ────────────────────────────────── */}
418	          <Card>
419	            <CardHeader>
420	              <CardTitle className="flex items-center gap-2 text-lg"><BookOpen className="h-4 w-4 text-primary" /> Reference games</CardTitle>
421	              <CardDescription>Games you're drawing from — the AI uses this to calibrate suggestions and avoid overlap.</CardDescription>
422	            </CardHeader>
423	            <CardContent className="space-y-3">
424	              {refGames.length > 0 && (
425	                <div className="rounded-md border border-border divide-y divide-border/50">
426	                  {refGames.map((rg, i) => (
