428	                      <div className="flex-1 min-w-0">
429	                        <p className="text-sm font-semibold text-white">{rg.name}</p>
430	                        {rg.borrowing && <p className="text-xs text-muted-foreground mt-0.5"><span className="text-emerald-400 font-medium">Borrowing:</span> {rg.borrowing}</p>}
431	                        {rg.avoiding && <p className="text-xs text-muted-foreground mt-0.5"><span className="text-red-400 font-medium">Avoiding:</span> {rg.avoiding}</p>}
432	                      </div>
433	                      <button onClick={() => saveRefGames(refGames.filter((_, j) => j !== i))} className="opacity-0 group-hover:opacity-100 text-muted-foreground hover:text-destructive transition-opacity p-1">
434	                        <X className="w-3.5 h-3.5" />
435	                      </button>
436	                    </div>
437	                  ))}
438	                </div>
439	              )}
440	
441	              {showRefForm ? (
442	                <div className="border border-border rounded-lg p-4 space-y-3 bg-muted/5">
443	                  <Input placeholder="Game name (e.g. Dominion)" value={refGameDraft.name} onChange={(e) => setRefGameDraft((d) => ({ ...d, name: e.target.value }))} />
444	                  <Input placeholder="What are you borrowing? (e.g. deck-building loop)" value={refGameDraft.borrowing} onChange={(e) => setRefGameDraft((d) => ({ ...d, borrowing: e.target.value }))} />
445	                  <Input placeholder="What are you avoiding? (e.g. eliminating players early)" value={refGameDraft.avoiding} onChange={(e) => setRefGameDraft((d) => ({ ...d, avoiding: e.target.value }))} />
446	                  <div className="flex gap-2">
447	                    <Button size="sm" onClick={() => {
448	                      if (!refGameDraft.name.trim()) return;
449	                      saveRefGames([...refGames, refGameDraft]);
450	                      setRefGameDraft({ name: "", borrowing: "", avoiding: "" });
451	                      setShowRefForm(false);
452	                    }} disabled={!refGameDraft.name.trim()}>
453	                      Add game
454	                    </Button>
455	                    <Button size="sm" variant="ghost" onClick={() => setShowRefForm(false)}>Cancel</Button>
456	                  </div>
457	                </div>
458	              ) : (
459	                <Button variant="outline" size="sm" className="gap-1.5" onClick={() => setShowRefForm(true)}>
460	                  <Plus className="w-3.5 h-3.5" /> Add reference game
461	                </Button>
462	              )}
463	            </CardContent>
464	          </Card>
465	
466	          <ProjectVersions projectId={projectId} />
467	        </div>
468	
469	        {/* ── Right column ─────────────────────────────────────────── */}
470	        <div className="space-y-6">
471	          {/* Complexity score */}
