473	            <ComplexityScore
474	              ruleCount={(stats as any).ruleCount ?? 0}
475	              entityCount={(stats as any).entityCount ?? 0}
476	              playerCount={formData.playerCount}
477	              playtestCount={(stats as any).playtestCount ?? 0}
478	            />
479	          )}
480	
481	          {/* Monopoly demo loader */}
482	          <Card className="border-amber-500/30 bg-amber-500/5">
483	            <CardHeader className="pb-2">
484	              <CardTitle className="flex items-center gap-2 text-amber-300 text-sm">
485	                🎩 Monopoly Demo Template
486	              </CardTitle>
