53	export function Research({ projectId }: { projectId: number }) {
54	  const qc = useQueryClient();
55	  const { toast } = useToast();
56	  const { data: items, isLoading } = useListResearch(projectId);
57	  const createItem = useCreateResearch();
58	  const updateItem = useUpdateResearch();
59	  const deleteItem = useDeleteResearch();
60	  const enhanceItem = useAiEnhanceResearch();
61	  const [enhancingId, setEnhancingId] = useState<number | null>(null);
62	
63	  const handleEnhance = async (researchId: number) => {
64	    setEnhancingId(researchId);
65	    try {
66	      await enhanceItem.mutateAsync({ projectId, researchId });
67	      qc.invalidateQueries({ queryKey: getListResearchQueryKey(projectId) });
68	      toast({ title: "Research enhanced", description: "AI improved the summary." });
69	    } catch (err) {
70	      toast({ title: "Enhance failed", description: err instanceof Error ? err.message : String(err), variant: "destructive" });
71	    } finally {
72	      setEnhancingId(null);
73	    }
74	  };
75	
76	  const [search, setSearch] = useState("");
77	  const [showAdd, setShowAdd] = useState(false);
78	  const [editing, setEditing] = useState<number | null>(null);
79	  const [form, setForm] = useState({ title: "", source: "", content: "", tags: "" });
80	
81	  const [showIngest, setShowIngest] = useState(false);
82	  const [ingestUrl, setIngestUrl] = useState("");
83	  const [ingestText, setIngestText] = useState("");
84	  const [ingesting, setIngesting] = useState(false);
85	
86	  const isFormOpen = showAdd || editing !== null;
87	
88	  const refresh = () => qc.invalidateQueries({ queryKey: getListResearchQueryKey(projectId) });
89	  const filtered = items?.filter(i => !search || (i.title + (i.content || "") + (i.tags || "")).toLowerCase().includes(search.toLowerCase()));
90	
91	  const closeForm = () => {
92	    setShowAdd(false);
93	    setEditing(null);
94	    setForm({ title: "", source: "", content: "", tags: "" });
95	  };
96	
97	  const openCreate = () => {
98	    setEditing(null);
99	    setForm({ title: "", source: "", content: "", tags: "" });
100	    setShowIngest(false);
101	    setShowAdd(true);
102	  };
103	
104	  const openEdit = (id: number) => {
105	    const it = items?.find(i => i.id === id);
106	    if (!it) return;
107	    setShowAdd(false);
108	    setShowIngest(false);
109	    setEditing(id);
110	    setForm({ title: it.title, source: it.source || "", content: it.content || "", tags: it.tags || "" });
111	  };
112	
113	  const submit = async (e: React.FormEvent) => {
114	    e.preventDefault();
115	    if (!form.title.trim()) return;
116	    try {
117	      if (editing) {
118	        await updateItem.mutateAsync({ projectId, researchId: editing, data: form });
119	      } else {
120	        await createItem.mutateAsync({ projectId, data: form });
121	      }
122	      closeForm(); refresh();
123	    } catch { toast({ title: "Save failed", variant: "destructive" }); }
124	  };
125	
126	  const removeItem = async (id: number) => {
127	    try { await deleteItem.mutateAsync({ projectId, researchId: id }); refresh(); }
128	    catch { toast({ title: "Delete failed", variant: "destructive" }); }
129	  };
130	
131	  const closeIngest = () => {
132	    setShowIngest(false);
133	    setIngestUrl("");
134	    setIngestText("");
135	  };
136	
137	  const ingest = async () => {
138	    if (!ingestUrl && !ingestText) return;
139	    setIngesting(true);
140	    try {
141	      const base = import.meta.env.BASE_URL.replace(/\/$/, "");
142	      const prompt = ingestUrl
143	        ? `Summarize the source at this URL into a research note: ${ingestUrl}`
144	        : `Summarize the following text into a single research note:\n\n${ingestText}`;
145	      const res = await fetch(`${base}/api/projects/${projectId}/research/ai-generate`, {
146	        method: "POST",
147	        headers: { "Content-Type": "application/json" },
148	        credentials: "include",
149	        body: JSON.stringify({ prompt, count: 1 }),
150	      });
151	      if (!res.ok) throw new Error("ingest failed");
152	      closeIngest();
153	      refresh();
154	      toast({ title: "Ingested", description: "AI summarized and added the source." });
155	    } catch { toast({ title: "Ingest failed", variant: "destructive" }); }
156	    finally { setIngesting(false); }
157	  };
158	
159	  return (
160	    <div className="space-y-6 max-w-6xl">
161	      <div className="flex items-end justify-between gap-4 flex-wrap">
162	        <div>
163	          <h2 className="text-2xl font-bold flex items-center gap-2"><BookOpen className="h-6 w-6 text-primary" /> Research</h2>
164	          <p className="text-muted-foreground text-sm mt-1">Capture inspirations, references, and design notes.</p>
165	        </div>
166	        <div className="flex gap-2">
167	          {!showIngest && !isFormOpen && (
168	            <Button variant="outline" onClick={() => { setShowAdd(false); setEditing(null); setShowIngest(true); }} className="gap-2"><Sparkles className="h-4 w-4" /> AI Ingest</Button>
169	          )}
170	          {!isFormOpen && !showIngest && (
171	            <Button onClick={openCreate} className="gap-2" data-testid="add-research-button"><Plus className="h-4 w-4" /> Add Source</Button>
172	          )}
173	        </div>
174	      </div>
175	
176	      {isFormOpen && (
177	        <Card className="bg-card border-primary/40" data-testid="research-form-panel">
178	          <CardHeader className="pb-3 flex flex-row items-center justify-between space-y-0">
179	            <CardTitle className="text-base">{editing ? "Edit research source" : "Add research source"}</CardTitle>
180	            <Button variant="ghost" size="icon" className="h-8 w-8" onClick={closeForm}><X className="h-4 w-4" /></Button>
181	          </CardHeader>
182	          <CardContent>
183	            <form onSubmit={submit} className="space-y-4">
184	              <div className="space-y-2"><Label>Title *</Label><Input value={form.title} onChange={e => setForm({...form, title: e.target.value})} required autoFocus /></div>
185	              <div className="space-y-2"><Label>Source URL or citation</Label><Input value={form.source} onChange={e => setForm({...form, source: e.target.value})} placeholder="https://..." /></div>
186	              <div className="space-y-2"><Label>Notes</Label><Textarea rows={5} value={form.content} onChange={e => setForm({...form, content: e.target.value})} /></div>
187	              <div className="space-y-2"><Label>Tags (comma-separated)</Label><Input value={form.tags} onChange={e => setForm({...form, tags: e.target.value})} placeholder="combat, economy" /></div>
188	              <div className="flex justify-end gap-2 pt-2">
189	                <Button type="button" variant="outline" onClick={closeForm}>Cancel</Button>
190	                <Button type="submit">{editing ? "Save" : "Add"}</Button>
191	              </div>
192	            </form>
193	          </CardContent>
194	        </Card>
195	      )}
196	
197	      {showIngest && (
198	        <Card className="bg-card border-primary/40" data-testid="research-ingest-panel">
199	          <CardHeader className="pb-3 flex flex-row items-center justify-between space-y-0">
200	            <div>
201	              <CardTitle className="text-base">AI Ingest</CardTitle>
202	              <p className="text-xs text-muted-foreground mt-1">Paste a URL or text and let AI summarize it into a research item.</p>
203	            </div>
204	            <Button variant="ghost" size="icon" className="h-8 w-8" onClick={closeIngest}><X className="h-4 w-4" /></Button>
205	          </CardHeader>
206	          <CardContent className="space-y-4">
