1	import { anthropic as defaultAnthropic, Anthropic } from "@workspace/integrations-anthropic-ai";
2	import { openai as defaultOpenAi, OpenAI } from "@workspace/integrations-openai-ai-server";
3	import { ai as defaultGemini, GoogleGenAI } from "@workspace/integrations-gemini-ai";
4	import { openrouter as defaultOpenRouter } from "@workspace/integrations-openrouter-ai";
5	import type { Request } from "express";
6	import { getAuth } from "@clerk/express";
7	import { eq } from "drizzle-orm";
8	import { db, appUsers, aiProviderSettings } from "@workspace/db";
9	import {
10	  getWorkspaceIdForRequest,
11	  getWorkspaceProviderSettings,
12	  AiProviderDisabledError,
13	  type WorkspaceProvider,
14	} from "./workspaceAiSettings";
15	
16	export { AiProviderDisabledError } from "./workspaceAiSettings";
17	
18	export type AiTaskKind =
19	  | "narrative"
20	  | "structured"
21	  | "image";
22	
23	export type AiProvider =
24	  | "anthropic"
25	  | "openai"
26	  | "gemini"
27	  | "openrouter";
28	
29	export interface ProviderChoice {
30	  provider: AiProvider;
31	  model: string;
32	}
33	
34	const DEFAULT_ANTHROPIC_MODEL = "claude-sonnet-4-6";
35	const FAST_ANTHROPIC_MODEL = "claude-haiku-4-5";
36	const DEFAULT_OPENAI_MODEL = "gpt-5.4";
37	const DEFAULT_GEMINI_MODEL = "gemini-3-flash-preview";
38	const FAST_GEMINI_MODEL = "gemini-3-flash-preview";
39	const PRO_GEMINI_MODEL = "gemini-3.1-pro-preview";
40	const DEFAULT_OPENROUTER_MODEL = "x-ai/grok-4-fast";
41	
42	export interface ModelOption {
43	  provider: AiProvider;
44	  model: string;
45	  label: string;
46	  family: "claude" | "gpt" | "gemini" | "grok" | "perplexity";
47	}
48	
49	export const AVAILABLE_MODELS: ModelOption[] = [
50	  { provider: "anthropic", model: "claude-sonnet-4-6", label: "Claude Sonnet 4.6 (best balance)", family: "claude" },
51	  { provider: "anthropic", model: "claude-haiku-4-5", label: "Claude Haiku 4.5 (fast)", family: "claude" },
52	  { provider: "openai", model: "gpt-5.4", label: "GPT-5.4 (smart)", family: "gpt" },
53	  { provider: "openai", model: "gpt-5-mini", label: "GPT-5 Mini (fast)", family: "gpt" },
54	  { provider: "gemini", model: "gemini-3.1-pro-preview", label: "Gemini 3.1 Pro (deep reasoning)", family: "gemini" },
55	  { provider: "gemini", model: "gemini-3-flash-preview", label: "Gemini 3 Flash (fast)", family: "gemini" },
56	  { provider: "openrouter", model: "x-ai/grok-4-fast", label: "Grok 4 Fast (xAI)", family: "grok" },
57	  { provider: "openrouter", model: "x-ai/grok-4", label: "Grok 4 (xAI)", family: "grok" },
58	  { provider: "openrouter", model: "perplexity/sonar", label: "Perplexity Sonar (web-aware)", family: "perplexity" },
59	  { provider: "openrouter", model: "perplexity/sonar-pro", label: "Perplexity Sonar Pro", family: "perplexity" },
60	];
61	
62	export async function getUserAiPreference(
63	  req: Request,
64	): Promise<{ provider: AiProvider; model: string | null } | null> {
65	  try {
66	    const { userId } = getAuth(req);
67	    if (!userId) return null;
68	    const [user] = await db
69	      .select()
70	      .from(appUsers)
71	      .where(eq(appUsers.clerkUserId, userId));
72	    if (!user) return null;
73	    const [pref] = await db
74	      .select()
75	      .from(aiProviderSettings)
76	      .where(eq(aiProviderSettings.userId, user.id));
77	    if (!pref) return null;
78	    const provider = (pref.provider as AiProvider) ?? "anthropic";
79	    if (!["anthropic", "openai", "gemini", "openrouter"].includes(provider)) {
80	      return { provider: "anthropic", model: null };
81	    }
82	    return { provider, model: pref.model ?? null };
83	  } catch {
84	    return null;
85	  }
86	}
87	
88	function defaultModelFor(provider: AiProvider, preferFast: boolean): string {
89	  if (provider === "anthropic") return preferFast ? FAST_ANTHROPIC_MODEL : DEFAULT_ANTHROPIC_MODEL;
90	  if (provider === "openai") return preferFast ? "gpt-5-mini" : DEFAULT_OPENAI_MODEL;
91	  if (provider === "gemini") return preferFast ? FAST_GEMINI_MODEL : PRO_GEMINI_MODEL;
92	  return DEFAULT_OPENROUTER_MODEL;
93	}
94	
95	export async function pickProvider(
96	  req: Request,
97	  kind: AiTaskKind,
98	  preferFast = false,
99	): Promise<ProviderChoice> {
100	  if (kind === "image") {
101	    return { provider: "openai", model: "gpt-image-1" };
102	  }
103	  const pref = await getUserAiPreference(req);
104	  // Narrative still defaults to Anthropic if user has no preference, since it's the most reliable for streaming.
105	  if (!pref) {
106	    return {
107	      provider: "anthropic",
108	      model: defaultModelFor("anthropic", preferFast),
109	    };
110	  }
111	  return {
112	    provider: pref.provider,
113	    model: pref.model ?? defaultModelFor(pref.provider, preferFast),
114	  };
115	}
116	
117	interface ResolvedClients {
118	  anthropic: typeof defaultAnthropic;
119	  openai: typeof defaultOpenAi;
120	  gemini: typeof defaultGemini;
121	  openrouter: typeof defaultOpenRouter;
122	}
123	
124	async function resolveProvider(
125	  req: Request,
126	  provider: AiProvider,
127	): Promise<{ apiKey: string | null }> {
128	  const wsId = await getWorkspaceIdForRequest(req);
129	  if (!wsId) return { apiKey: null };
130	  const settings = await getWorkspaceProviderSettings(wsId, provider as WorkspaceProvider);
131	  if (!settings.enabled) throw new AiProviderDisabledError(provider as WorkspaceProvider);
132	  return { apiKey: settings.apiKey };
133	}
134	
135	function buildAnthropicClient(apiKey: string | null): typeof defaultAnthropic {
136	  if (!apiKey) return defaultAnthropic;
137	  return new Anthropic({ apiKey }) as unknown as typeof defaultAnthropic;
138	}
139	
140	function buildOpenAiClient(apiKey: string | null): typeof defaultOpenAi {
141	  if (!apiKey) return defaultOpenAi;
142	  return new OpenAI({ apiKey }) as unknown as typeof defaultOpenAi;
143	}
144	
145	function buildGeminiClient(apiKey: string | null): typeof defaultGemini {
146	  if (!apiKey) return defaultGemini;
147	  return new GoogleGenAI({ apiKey }) as unknown as typeof defaultGemini;
148	}
149	
150	function buildOpenRouterClient(apiKey: string | null): typeof defaultOpenRouter {
151	  if (!apiKey) return defaultOpenRouter;
152	  return new OpenAI({
153	    apiKey,
154	    baseURL: "https://openrouter.ai/api/v1",
155	  }) as unknown as typeof defaultOpenRouter;
156	}
157	
158	async function resolveClients(req: Request, choice: ProviderChoice): Promise<ResolvedClients> {
159	  const { apiKey } = await resolveProvider(req, choice.provider);
160	  return {
161	    anthropic: choice.provider === "anthropic" ? buildAnthropicClient(apiKey) : defaultAnthropic,
162	    openai: choice.provider === "openai" ? buildOpenAiClient(apiKey) : defaultOpenAi,
163	    gemini: choice.provider === "gemini" ? buildGeminiClient(apiKey) : defaultGemini,
164	    openrouter: choice.provider === "openrouter" ? buildOpenRouterClient(apiKey) : defaultOpenRouter,
165	  };
166	}
167	
168	export interface CompleteOptions {
169	  system?: string;
170	  prompt: string;
171	  maxTokens?: number;
172	  preferFast?: boolean;
173	  kind?: AiTaskKind;
174	}
175	
176	export async function complete(
177	  req: Request,
178	  opts: CompleteOptions,
179	): Promise<string> {
180	  const choice = await pickProvider(
181	    req,
182	    opts.kind ?? "structured",
183	    opts.preferFast ?? false,
184	  );
185	  const max = opts.maxTokens ?? 2048;
186	  const clients = await resolveClients(req, choice);
187	
188	  if (choice.provider === "openai" || choice.provider === "openrouter") {
189	    const client = choice.provider === "openai" ? clients.openai : clients.openrouter;
190	    const messages: Array<{ role: "system" | "user"; content: string }> = [];
191	    if (opts.system) messages.push({ role: "system", content: opts.system });
192	    messages.push({ role: "user", content: opts.prompt });
193	    const r = await client.chat.completions.create({
194	      model: choice.model,
195	      max_completion_tokens: max,
196	      messages,
197	    });
198	    return r.choices[0]?.message?.content ?? "";
199	  }
200	
201	  if (choice.provider === "gemini") {
202	    const r = await clients.gemini.models.generateContent({
203	      model: choice.model,
204	      contents: opts.prompt,
205	      config: opts.system
206	        ? { systemInstruction: opts.system, maxOutputTokens: max }
207	        : { maxOutputTokens: max },
208	    });
209	    return r.text ?? "";
210	  }
211	
212	  const message = await clients.anthropic.messages.create({
213	    model: choice.model,
214	    max_tokens: max,
215	    system: opts.system,
216	    messages: [{ role: "user", content: opts.prompt }],
217	  });
218	  const block = message.content[0];
219	  return block && block.type === "text" ? block.text : "";
220	}
221	
222	export interface StreamOptions {
223	  system?: string;
224	  messages: Array<{ role: "user" | "assistant"; content: string }>;
225	  maxTokens?: number;
226	  preferFast?: boolean;
227	  kind?: AiTaskKind;
228	  onChunk: (text: string) => void;
229	}
230	
231	export async function stream(
232	  req: Request,
233	  opts: StreamOptions,
234	): Promise<{ provider: AiProvider; model: string; text: string }> {
235	  const choice = await pickProvider(
236	    req,
237	    opts.kind ?? "narrative",
238	    opts.preferFast ?? false,
239	  );
240	  const max = opts.maxTokens ?? 2048;
241	  const clients = await resolveClients(req, choice);
242	  let text = "";
243	
244	  if (choice.provider === "openai" || choice.provider === "openrouter") {
245	    const client = choice.provider === "openai" ? clients.openai : clients.openrouter;
246	    const all: Array<{ role: "system" | "user" | "assistant"; content: string }> = [];
247	    if (opts.system) all.push({ role: "system", content: opts.system });
248	    for (const m of opts.messages) all.push(m);
249	    const s = await client.chat.completions.create({
250	      model: choice.model,
251	      max_completion_tokens: max,
252	      messages: all,
253	      stream: true,
254	    });
255	    for await (const chunk of s) {
256	      const piece = chunk.choices[0]?.delta?.content;
257	      if (piece) {
258	        text += piece;
259	        opts.onChunk(piece);
260	      }
261	    }
262	    return { provider: choice.provider, model: choice.model, text };
263	  }
264	
265	  if (choice.provider === "gemini") {
266	    const stream = await clients.gemini.models.generateContentStream({
267	      model: choice.model,
268	      contents: opts.messages.map((m) => ({
269	        role: m.role === "assistant" ? "model" : "user",
270	        parts: [{ text: m.content }],
271	      })),
272	      config: opts.system
273	        ? { systemInstruction: opts.system, maxOutputTokens: max }
274	        : { maxOutputTokens: max },
275	    });
276	    for await (const chunk of stream) {
277	      const piece = chunk.text;
278	      if (piece) {
279	        text += piece;
280	        opts.onChunk(piece);
281	      }
282	    }
283	    return { provider: choice.provider, model: choice.model, text };
284	  }
285	
286	  const s = await clients.anthropic.messages.stream({
287	    model: choice.model,
288	    max_tokens: max,
289	    system: opts.system,
290	    messages: opts.messages,
291	  });
292	  for await (const event of s) {
293	    if (
294	      event.type === "content_block_delta" &&
295	      event.delta.type === "text_delta"
296	    ) {
297	      const piece = event.delta.text;
298	      text += piece;
299	      opts.onChunk(piece);
300	    }
301	  }
302	  return { provider: choice.provider, model: choice.model, text };
303	}
304	
305	export function tryParseJsonArray<T = unknown>(text: string): T[] {
306	  const cleaned = text
307	    .trim()
308	    .replace(/^```json\s*/i, "")
309	    .replace(/^```/, "")
310	    .replace(/```$/, "")
311	    .trim();
312	  try {
313	    const v = JSON.parse(cleaned);
314	    return Array.isArray(v) ? v : [];
315	  } catch {
316	    const match = cleaned.match(/\[[\s\S]*\]/);
317	    if (match) {
318	      try {
319	        const v = JSON.parse(match[0]);
320	        return Array.isArray(v) ? v : [];
321	      } catch {
322	        return [];
323	      }
324	    }
325	    return [];
326	  }
327	}
328	
329	export function tryParseJsonObject<T = Record<string, unknown>>(
330	  text: string,
331	): T | null {
332	  const cleaned = text
333	    .trim()
334	    .replace(/^```json\s*/i, "")
335	    .replace(/^```/, "")
336	    .replace(/```$/, "")
337	    .trim();
338	  try {
339	    return JSON.parse(cleaned) as T;
340	  } catch {
341	    const match = cleaned.match(/\{[\s\S]*\}/);
342	    if (match) {
343	      try {
344	        return JSON.parse(match[0]) as T;
345	      } catch {
346	        // fall through to repair
347	      }
348	    }
349	    const repaired = repairTruncatedJsonObject(cleaned);
350	    if (repaired) {
351	      try {
352	        return JSON.parse(repaired) as T;
353	      } catch {
354	        return null;
355	      }
356	    }
357	    return null;
358	  }
359	}
360	
361	// Pick string fields from a parsed AI JSON response, tolerating wrapped
362	// shapes such as {"player": {...}}, {"data": {...}}, or {"result": {...}}.
363	// If no allowed keys are found at the top level, looks EXACTLY one level
364	// deep into immediate child object values and returns the first match.
365	// Does not recurse further — deeper matches are intentionally ignored to
366	// avoid pulling allowed-key names from unrelated nested noise.
367	// Empty strings are skipped.
368	export function pickStringFields(
369	  obj: unknown,
370	  allowed: readonly string[],
371	): Record<string, string> {
372	  const pickFlat = (v: unknown): Record<string, string> => {
373	    const result: Record<string, string> = {};
374	    if (!v || typeof v !== "object" || Array.isArray(v)) return result;
375	    const rec = v as Record<string, unknown>;
376	    for (const k of allowed) {
377	      const val = rec[k];
378	      if (typeof val === "string" && val.trim().length > 0) {
