10	router.get("/projects/:projectId/research", async (req, res): Promise<void> => {
11	  const params = schemas.ListResearchParams.safeParse(req.params);
12	  if (!params.success) {
13	    res.status(400).json({ error: params.error.message });
14	    return;
15	  }
16	  const rows = await db
17	    .select()
18	    .from(researchItems)
19	    .where(eq(researchItems.projectId, params.data.projectId))
20	    .orderBy(desc(researchItems.createdAt));
21	  res.json(schemas.ListResearchResponse.parse(rows));
22	});
