24	router.post("/projects/:projectId/research", async (req, res): Promise<void> => {
25	  const params = schemas.CreateResearchParams.safeParse(req.params);
26	  if (!params.success) {
27	    res.status(400).json({ error: params.error.message });
28	    return;
29	  }
30	  const parsed = schemas.CreateResearchBody.safeParse(req.body);
31	  if (!parsed.success) {
32	    res.status(400).json({ error: parsed.error.message });
33	    return;
34	  }
35	  const [row] = await db
36	    .insert(researchItems)
37	    .values({ ...parsed.data, projectId: params.data.projectId })
38	    .returning();
39	  await logChange(req, params.data.projectId, "create", `Added research: ${row!.title}`, {
40	    entityKind: "research",
41	    entityRef: String(row!.id),
42	  });
43	  res.status(201).json(row);
44	});
45	
46	router.patch(
